const translateStatus = (value: string, lang: Lang) => lang === 'en' ? ({'نشط':'Active','قيد المراجعة':'Pending','معتمد':'Approved','مرفوض':'Rejected','منتهي':'Expired','مسدد':'Paid','حاضر':'Present','متأخر':'Late','غائب':'Absent','عن بُعد':'Remote','جاهز':'Ready','قيد المعالجة':'Processing'}[value] || value) : value;
const number = (value: number, lang: Lang) => new Intl.NumberFormat(lang === 'ar' ? 'ar-SA' : 'en-US').format(value);
const expiryDays = (date?: string) => date ? Math.ceil((new Date(`${date}T00:00:00`).getTime() - new Date(new Date().toDateString()).getTime()) / 86400000) : null;
const expiryBand = (days: number) => days <= 7 ? 7 : days <= 15 ? 15 : days <= 30 ? 30 : 45;
const initialData = Object.fromEntries(modules.map(m => [m.key, m.sample]));

