        {active==='settings'&&<section className="module-view"><div className="page-heading"><div><p className="eyebrow">{isAr?'إعدادات المؤسسة':'Organization setup'}</p><h1>{t('settings')}</h1><p>{isAr?'تخصيص الدولة، العملة، اللغة، وإدارة الوصول':'Configure regional settings, language, and access controls'}</p></div></div><div className="panel settings-panel"><form className="regional-settings-form" onSubmit={saveOrganizationSettings}><div className="panel-head"><div><h2>{t('countrySettings')}</h2><p>{t('regionDetails')}</p></div></div>{user?.role==='admin'||!remoteMode?<div className="regional-fields"><label className="form-field"><span>{t('country')}</span><select value={organizationSettings.countryCode} onChange={event=>{const profile=organizationSettings.countries.find(item=>item.code===event.target.value)||defaultCountries.find(item=>item.code===event.target.value);if(profile)setOrganizationSettings(value=>({...value,countryCode:profile.code,currencyCode:profile.currency,locale:profile.locale,timezone:profile.timezone,dateFormat:profile.dateFormat,weekStart:profile.weekStart,weekendDays:profile.weekendDays}));}}>{organizationSettings.countries.map(profile=><option key={profile.code} value={profile.code}>{isAr?profile.nameAr:profile.nameEn}</option>)}</select></label><label className="form-field"><span>{t('currency')}</span><select value={organizationSettings.currencyCode} onChange={event=>setOrganizationSettings(value=>({...value,currencyCode:event.target.value}))}>{Array.from(new Set(organizationSettings.countries.map(profile=>profile.currency))).map(currency=><option key={currency} value={currency}>{currency}</option>)}</select></label><button className="primary-btn"><Check size={16}/>{t('saveSettings')}</button></div>:<div className="regional-readonly"><b>{organizationSettings.countries.find(item=>item.code===organizationSettings.countryCode)?.[isAr?'nameAr':'nameEn']}</b><span>{organizationSettings.currencyCode}</span></div>}<div className="region-meta"><span>{isAr?'المنطقة الزمنية':'Timezone'}: {organizationSettings.timezone}</span><span>{isAr?'صيغة التاريخ':'Date format'}: {organizationSettings.dateFormat}</span><span>{isAr?'عطلة الأسبوع':'Weekend'}: {organizationSettings.weekendDays.map(day=>isAr?['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'][day]:['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][day]).join(isAr?'، ':' / ')}</span></div></form><div className="setting-row"><span className="setting-icon"><Globe2 size={19}/></span><div><b>{isAr?'لغة الواجهة':'Interface language'}</b><small>{isAr?'اختر لغة عرض النظام':'Choose the display language'}</small></div><button className="language-btn" onClick={()=>setLang(isAr?'en':'ar')}>{isAr?'العربية':'English'} <ChevronDown size={15}/></button></div><div className="setting-row"><span className="setting-icon"><ShieldCheck size={19}/></span><div><b>{isAr?'الخصوصية والتخزين':'Privacy & storage'}</b><small>{remoteMode?(isAr?'قاعدة البيانات والوثائق محفوظة محلياً على الجهاز المضيف':'Database and files are stored on the local host'):(isAr?'البيانات محفوظة محلياً في هذا المتصفح':'Data is stored locally in this browser')}</small></div><button className="secondary-btn" onClick={()=>remoteMode?void createBackup():window.confirm(isAr?'مسح كل البيانات المحفوظة وإعادة البيانات التجريبية؟':'Clear saved data and restore demo data?')&&(localStorage.removeItem('rakeza-data'),setData(initialData),setToast(isAr?'تمت استعادة البيانات التجريبية':'Demo data restored'))}>{remoteMode?(isAr?'إنشاء نسخة احتياطية':'Create backup'):(isAr?'استعادة البيانات التجريبية':'Restore demo data')}</button></div>{remoteMode&&onChangeDeployment&&user?.role==='admin'&&<div className="setting-row"><span className="setting-icon"><Globe2 size={19}/></span><div><b>{t('changeDeviceMode')}</b><small>{t('changeDeviceModeHint')}</small></div><button className="secondary-btn" onClick={()=>window.confirm(isAr?'سيعاد تشغيل البرنامج لاختيار نمط الجهاز. متابعة؟':'The app will restart to change device mode. Continue?')&&onChangeDeployment()}>{t('changeDeviceMode')}</button></div>}</div></section>}
        {active==='settings'&&organizationSettings.countryCode==='SA'&&<section className="panel saudi-compliance-panel"><div className="panel-head"><div><p className="eyebrow">{isAr?'ملف السعودية':'Saudi Arabia profile'}</p><h2>{isAr?'القواعد النظامية المرجعية':'Regulatory reference rules'}</h2><p>{isAr?'مراجعة المصادر الرسمية: 10 نوفمبر 2026. النتائج تقديرية وتتطلب اعتماداً بشرياً.':'Official sources reviewed: 10 Nov 2026. Estimates require human approval.'}</p></div><span className="compliance-badge">{isAr?'مرجع تقديري':'Advisory'}</span></div><div className="compliance-rule-grid"><article><b>{isAr?'الإجازة السنوية':'Annual leave'}</b><p>{isAr?'21 يوماً سنوياً، وترتفع إلى 30 بعد خمس سنوات متصلة.':'21 days/year; 30 after five consecutive years.'}</p></article><article><b>{isAr?'نهاية الخدمة':'End of service'}</b><p>{isAr?'نصف أجر شهر لكل سنة من أول خمس سنوات، ثم أجر شهر لكل سنة تالية.':'Half a month per year for the first five years, then one month per year.'}</p></article><article><b>{isAr?'التأمينات الاجتماعية':'Social insurance'}</b><p>{isAr?'تختلف حسب سجل المشترك. النظام الجديد وصل في 2026 إلى 10% معاشات لكل طرف؛ لا تستخدم النسبة دون تأكيد GOSI.':'Depends on the member record. The new scheme is 10% pension per party in 2026; confirm GOSI membership first.'}</p></article><article><b>{isAr?'العمل الإضافي':'Overtime'}</b><p>{isAr?'أجر الساعة مضافاً إليه 50% من الأجر الأساسي للساعة؛ يلزم التحقق من فئة العامل وساعات العمل.':'Hourly wage plus 50% of basic hourly wage; worker category and working hours must be checked.'}</p></article></div><p className="compliance-disclaimer">{isAr?'هذه قواعد مساعدة وليست اعتماداً قانونياً أو مسيراً للرواتب. بعض الفئات والاستثناءات والحالات الانتقالية تحتاج مراجعة مختص؛ لا ينشئ النظام خصومات أو قيوداً محاسبية من التقديرات.':'These rules are guidance, not legal approval or payroll posting. Exceptions and transition cases require review; estimates never create deductions or accounting entries.'} <a href="https://www.hrsd.gov.sa/%D8%B9%D9%84%D8%A7%D9%82%D8%A7%D8%AA-%D8%A7%D9%84%D8%B9%D9%85%D9%84" target="_blank" rel="noreferrer">HRSD</a> · <a href="https://beta.gosi.gov.sa/new-system" target="_blank" rel="noreferrer">GOSI</a></p></section>}        {active==='settings'&&organizationSettings.countryCode==='AE'&&<section className="panel saudi-compliance-panel"><div className="panel-head"><div><p className="eyebrow">{isAr?'ملف الإمارات':'United Arab Emirates profile'}</p><h2>{isAr?'القواعد الاتحادية المرجعية':'Federal regulatory reference rules'}</h2><p>{isAr?'مراجعة المصادر الرسمية: 10 نوفمبر 2026. لا تشمل المناطق الحرة ذات الأنظمة المستقلة.':'Official sources reviewed: 10 Nov 2026. Free zones with separate regimes are excluded.'}</p></div><span className="compliance-badge">{isAr?'مرجع تقديري':'Advisory'}</span></div><div className="compliance-rule-grid"><article><b>{isAr?'الإجازة السنوية':'Annual leave'}</b><p>{isAr?'30 يوماً بعد سنة خدمة؛ ويومان شهرياً بعد 6 أشهر وقبل إكمال السنة.':'30 days after one year; two days/month after six months and before one year.'}</p></article><article><b>{isAr?'نهاية الخدمة':'End of service'}</b><p>{isAr?'للعامل الأجنبي بدوام كامل: 21 يوماً من الأجر الأساسي لكل سنة من أول خمس سنوات، ثم 30 يوماً، بسقف أجر سنتين.':'Foreign full-time workers: 21 basic-wage days per year for the first five years, then 30, capped at two years’ wage.'}</p></article><article><b>{isAr?'المعاشات الاتحادية GPSSA':'Federal pensions (GPSSA)'}</b><p>{isAr?'النظام الجديد: 11% على الموظف و15% على جهة العمل للمشمولين المؤكدين. تختلف الجهة والنسبة بحسب الإمارة والعضوية.':'New scheme: 11% employee and 15% employer for confirmed members. Authority and coverage vary by emirate and membership.'}</p></article><article><b>{isAr?'العمل الإضافي':'Overtime'}</b><p>{isAr?'25% زيادة على الأجر الأساسي للساعة، و50% بين 10م و4ص لغير العاملين بنظام الورديات.':'At least 25% above basic hourly wage; 50% between 10pm–4am for non-shift workers.'}</p></article></div><p className="compliance-disclaimer">{isAr?'التقديرات لا تُرحّل للرواتب. أبوظبي وصندوق الشارقة الحكومي والمناطق الحرة وبعض فئات العمل تحتاج قواعد مستقلة.':'Estimates are not posted to payroll. Abu Dhabi, Sharjah government, free zones, and some worker categories require separate rules.'} <a href="https://u.ae/en/information-and-services/jobs/employment-in-the-private-sector/employment-laws-and-regulations-in-the-private-sector" target="_blank" rel="noreferrer">MOHRE / U.AE</a> · <a href="https://gpssa.gov.ae/pages/en/media-center/news/gpssa-reviews-most-prominent-features-federal-law-no-57-2023" target="_blank" rel="noreferrer">GPSSA</a></p></section>}        {active==='settings'&&['SA','AE','BH','KW','OM','EG','JO','IQ','MA'].includes(organizationSettings.countryCode)&&<RegionalEstimator isAr={isAr} countryCode={organizationSettings.countryCode} currencyCode={organizationSettings.currencyCode} enabled={remoteMode&&can('payroll')} result={saudiEstimate} onEstimate={runRegionalEstimate}/>}        {active==='settings'&&remoteMode&&user?.role==='admin'&&<><section className="panel user-admin-panel"><div className="panel-head"><div><h2>{t('userAccounts')}</h2><p>{isAr?'أنشئ المستخدمين وعيّن لكل مستخدم دوراً':'Create users and assign their roles'}</p></div></div><form className="user-create-form" onSubmit={createTeamUser}><label className="form-field"><span>{t('userFullName')}</span><input name="fullName" required/></label><label className="form-field"><span>{isAr?'البريد الإلكتروني':'Email'}</span><input name="email" type="email" required/></label><label className="form-field"><span>{t('userRole')}</span><select name="role" defaultValue="hr">{roleDefinitions.map(role=><option key={role.key} value={role.key}>{roleName(role.key)}</option>)}</select></label><label className="form-field"><span>{t('passwordMin')}</span><input name="password" type="password" minLength={12} required/></label><button className="primary-btn"><Plus size={16}/>{t('addUser')}</button></form><div className="team-user-list">{teamUsers.map(item=><div className="team-user-row" key={item.id}><span className="profile-avatar">{item.fullName.split(' ').slice(0,2).map(x=>x[0]).join('')}</span><span className="team-user-copy"><b>{item.fullName}</b><small>{item.email}</small></span><select className="team-user-role-select" value={item.role} disabled={item.id===user.id} onChange={event=>void assignTeamRole(item,event.target.value)} aria-label={`${t('userRole')}: ${item.fullName}`}>{roleDefinitions.map(role=><option key={role.key} value={role.key}>{roleName(role.key)}</option>)}</select><span className={`team-user-state ${item.isActive?'team-user-state--active':''}`}>{item.isActive?t('active'):t('inactive')}</span><button className="secondary-btn" disabled={item.id===user.id} onClick={()=>void toggleTeamUser(item)}>{item.isActive?t('deactivate'):t('activate')}</button></div>)}</div></section><section className="panel permissions-panel"><div className="panel-head"><div><h2>{t('permissionSettings')}</h2><p>{t('permissionsHint')}</p></div></div><div className="permissions-toolbar"><label className="form-field"><span>{t('userRole')}</span><select value={selectedRole} onChange={event=>setSelectedRole(event.target.value)}>{roleDefinitions.filter(role=>role.key!=='admin').map(role=><option key={role.key} value={role.key}>{roleName(role.key)}</option>)}</select></label><button className="primary-btn" disabled={selectedRole==='admin'} onClick={()=>void saveRolePermissions()}><Check size={16}/>{t('savePermissions')}</button></div><div className="permissions-scroll"><table className="permissions-table"><thead><tr><th>{isAr?'الوحدة':'Module'}</th>{roleActions.map(action=><th key={action}>{t(action==='delete'?'remove':action)}</th>)}</tr></thead><tbody>{roleModules.map(module=><tr key={module}><th>{moduleLabel(module)}</th>{roleActions.map(action=><td key={action}><input type="checkbox" checked={Boolean(permissionDraft[module]?.[action])} onChange={event=>setPermissionDraft(previous=>({...previous,[module]:{...previous[module],[action]:event.target.checked}}))} aria-label={`${moduleLabel(module)} - ${t(action==='delete'?'remove':action)}`}/></td>)}</tr>)}</tbody></table></div><p className="permissions-note">{isAr?'دور مدير النظام محمي ويملك جميع الصلاحيات. التغييرات تسري فوراً على المستخدمين الذين يحملون الدور.':'The system administrator role is protected. Changes apply immediately to everyone assigned to the selected role.'}</p></section></>}
        {active==='about'&&<section className="module-view info-page"><div className="page-heading"><div><p className="eyebrow">{isAr?'منصة ركيزة':'Rakeza platform'}</p><h1>{t('about')}</h1><p>{t('aboutTagline')}</p></div></div><article className="panel about-hero"><div className="about-mark"><img src="/rakeza-mark.jpg" alt="Rakeza HR"/></div><div><span className="about-brand">{t('brand')}</span><h2>{t('aboutTagline')}</h2><p>{t('aboutDescription')}</p></div></article><div className="about-feature-grid"><article className="panel about-feature"><span className="quick-icon tone-navy"><Users size={20}/></span><b>{t('aboutPeople')}</b></article><article className="panel about-feature"><span className="quick-icon tone-teal"><ShieldCheck size={20}/></span><b>{t('aboutDocs')}</b></article><article className="panel about-feature"><span className="quick-icon tone-purple"><ChartNoAxesCombined size={20}/></span><b>{t('aboutInsights')}</b></article></div></section>}
